import React from 'react';
import { Box, Container } from '@mui/material';
import Slider from 'react-slick';
import 'slick-carousel/slick/slick.css';
import 'slick-carousel/slick/slick-theme.css';

const EventsSlider = () => {
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 1,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 3000,
    arrows: true,
  };

  const slides = [
    {
      id: 1,
      image: "https://www.techcareer.net/_next/image?url=https%3A%2F%2Fcdn.gcp.techcareer.net%2F2024_duyurular_1112x412_ccf8c238f3%2F2024_duyurular_1112x412_ccf8c238f3.png&w=1200&q=100",
      alt: "2024 Duyurular",
      link: "https://www.techcareer.net/courses"
    },
    {
      id: 2,
      image: "https://www.techcareer.net/_next/image?url=https%3A%2F%2Fcdn.gcp.techcareer.net%2Fluxoft_hackathon_1112x412_3468c22c84%2Fluxoft_hackathon_1112x412_3468c22c84.png&w=1200&q=100",
      alt: "Luxoft Hackathon",
      link: "https://www.techcareer.net/jobs"
    },
    {
      id: 3,
      image: "https://www.techcareer.net/_next/image?url=https%3A%2F%2Fcdn.gcp.techcareer.net%2FTwitch_1112_412_1_de33d89d8e%2FTwitch_1112_412_1_de33d89d8e.png&w=1200&q=100",
      alt: "Twitch",
      link: "https://www.techcareer.net/blog"
    }
  ];

  return (
    <Box
      className="background-container"
      sx={{
        position: 'relative',
        width: '100%',
        '&:before': {
          content: '""',
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: 'url(path-to-dots-background)', // dots background
          zIndex: 0
        },
        '&:after': {
          content: '""',
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: 'url(path-to-lines-background)', // lines background
          zIndex: 0
        }
      }}
    >
      <Container 
        sx={{ 
          height: '600px',
          padding: '48px',
          position: 'relative',
          zIndex: 1
        }}
      >
        <Box
          sx={{
            height: '500px',
            '.slick-dots': {
              bottom: '20px',
              zIndex: 2,
              '& li button:before': {
                color: '#fff',
              },
              '& li.slick-active button:before': {
                color: '#fff',
              }
            },
            '.slick-prev, .slick-next': {
              zIndex: 2,
              '&:before': {
                fontSize: '24px'
              }
            }
          }}
        >
          <Slider {...settings}>
            {slides.map((slide) => (
              <Box
                key={slide.id}
                component="a"
                href={slide.link}
                sx={{
                  display: 'block',
                  height: '429px',
                  '& img': {
                    width: '100%',
                    height: '100%',
                    objectFit: 'cover',
                    boxShadow: '0 0 15px rgba(0, 255, 0, 0.3)', // shadow-green equivalent
                  }
                }}
              >
                <img
                  src={slide.image}
                  alt={slide.alt}
                />
              </Box>
            ))}
          </Slider>
        </Box>
      </Container>
      <Box 
        className="background-tape"
        sx={{
          position: 'absolute',
          bottom: 0,
          left: 0,
          right: 0,
          height: '20px', // adjust based on your needs
          background: 'url(path-to-tape-background)' // tape background
        }}
      />
    </Box>
  );
};

export default EventsSlider;
